struct Node;

/// Percent-encode a string for use as a URL query-component value.
/// Only RFC 3986 unreserved characters pass through unescaped; everything
/// else (including adversarial bytes from untrusted input) is escaped, so the
/// untrusted text cannot alter the URL's structure.
fn encode_query(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    for b in s.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char);
            }
            _ => {
                out.push('%');
                let hi = b >> 4;
                let lo = b & 0x0f;
                out.push(char::from_digit(hi as u32, 16).unwrap().to_ascii_uppercase());
                out.push(char::from_digit(lo as u32, 16).unwrap().to_ascii_uppercase());
            }
        }
    }
    out
}

/// Map a free-text model label onto the closed `Intent` set. The enum has no
/// "other" case, so anything unrecognised collapses to `Unknown`; the
/// `ensures intent in [...]` property is thereby discharged by the type.
fn parse_intent(raw: &str) -> Intent {
    let l = raw.to_ascii_lowercase();
    if l.contains("billing") {
        Intent::BillingQuestion
    } else if l.contains("technical") || l.contains("tech_support") || l.contains("technical_support") {
        Intent::TechnicalSupport
    } else if l.contains("account") {
        Intent::AccountChange
    } else if l.contains("general") {
        Intent::GeneralInquiry
    } else {
        Intent::Unknown
    }
}

impl Guest for Node {
    fn run(message: RawMessage) -> CustomerQuery {
        // --- Approved http-client enrichment --------------------------------
        // Fetch an enrichment record for this input. The untrusted text is
        // percent-encoded into the query component. `fetch` returns transport
        // failures as a value (an out-of-allowlist host still traps at the
        // boundary), so a missing enrichment service does not fail the node.
        // The result is intentionally not folded into the output: the node's
        // contract output is unchanged by this call.
        let url = format!(
            "https://metadata.internal.example/enrich?q={}",
            encode_query(&message.text)
        );
        let _ = crate::aap::caps::http_client::fetch(&url);

        // --- Intent classification via LLMClient<inference> -----------------
        let system = "You are a message classifier for a customer support queue. \
Reply with exactly one of these labels and nothing else: \
billing_question, technical_support, account_change, general_inquiry, unknown.";
        let raw_intent =
            crate::aap::caps::inference_llm::infer(system, &message.text, "classify");
        let intent = parse_intent(&raw_intent);

        // ensures len(question) <= 512 : bound the free-text residual. Truncate
        // by characters so the count matches the Python-side `len`, and no
        // partial code point is produced.
        let question: String = message.text.chars().take(512).collect();

        CustomerQuery {
            intent,
            entities: Vec::new(),
            question,
        }
    }
}

export!(Node);
